    def partition(self, s: str) -> List[List[str]]:
        def is_palindrome(s):
            return s == s[::-1]

        def backtrack(index, path, result):
            if index == len(s):
                result.append(path[:])
                return

            for i in range(index, len(s)):
                if is_palindrome(s[index:i+1]):
                    path.append(s[index:i+1])
                    backtrack(i+1, path, result)
                    path.pop()

        result = []
        backtrack(0, [], result)
        return result`
