下面是一个简单的示例，展示了如何利用队列来管理并发请求：

```javascript
const asyncQueue = (fn, limit) => {
  const pending = [];

  const processQueue = () => {
    if (pending.length === 0) {
      return;
    }

    if (pending.length < limit) {
      const fnExecutor = async (...args) => {
        try {
          await fn(...args);
          pending.shift();
        } catch (error) {
          console.error(`Request failed with error: ${error}`);
          pending.shift();
        }
      };

      pending[0].resolve(fnExecutor(...pending[0].args));
    }

    setTimeout(() => processQueue(), 0);
  };

  return (...args) => {
    return new Promise((resolve, reject) => {
      pending.push({ resolve, reject, args });
      processQueue();
    });
  };
};

