/* 生成在标准区间[-1 1]均匀分布的随机数 */
#include <stdio.h>
#include <time.h>
#include <stdlib.h>

int main() {
    int r, count = 0;
    struct timespec start, stop;

    srand(time(NULL));

    double x;

    while(1) {
        x = (double)rand() / RAND_MAX;
        x *= 2;
        x -= 1;

        r = rand() %% 10000;
        if (r == x) {
            printf("找到随机数：%.2f\n", x);
            printf("每10000次生成的次数：%d\n", count);
            break;
        }
        count++;
    }

    return 0;
}

